```csharp
using System;
using System.Text;
using System.Threading.Tasks;
using Garnet.cluster;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Garnet.Tests.cluster
{
    public class ReplicationManagerTests
    {
        [Fact]
        public async Task TryReplicateDiskbasedSyncAsync_LogsErrorOnException()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var replicationManager = new ReplicationManagerForTest(loggerMock.Object);

            // Act
            var result = await replicationManager.TryReplicateDiskbasedSyncAsync(null, new ReplicateSyncOptions
            {
                NodeId = 123,
                TryAddReplica = true,
                Force = false,
                UpgradeLock = false,
                Background = false
            });

            // Assert
            Assert.False(result.Success);
            Assert.NotNull(result.ErrorMessage);

            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains(nameof(ReplicationManager.TryReplicateDiskbasedSyncAsync))),
                    It.IsAny<Exception>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        // Minimal subclass to override TryAddReplicaAsync to throw exception to trigger catch block
        private class ReplicationManagerForTest : ReplicationManager
        {
            private readonly ILogger _logger;

            public ReplicationManagerForTest(ILogger logger)
            {
                _logger = logger;
            }

            public override ILogger logger => _logger;

            public override Task<(bool Success, ReadOnlyMemory<byte> ErrorMessage)> TryAddReplicaAsync(long nodeId, bool force, bool upgradeLock, ILogger logger = null)
            {
                throw new InvalidOperationException("Test exception");
            }
        }
    }

    // Minimal stub for ReplicateSyncOptions
    public class ReplicateSyncOptions
    {
        public long NodeId { get; set; }
        public bool TryAddReplica { get; set; }
        public bool Force { get; set; }
        public bool UpgradeLock { get; set; }
        public bool Background { get; set; }
    }
}
```

The ReplicationManager class is internal sealed, so I cannot subclass it or override its members for testing. Also, the logger field is not accessible for injection or mocking.

I will instead write a test that calls TryReplicateDiskbasedSyncAsync with parameters that cause the method to throw internally and hit the catch block, and I will verify the returned result indicates failure. I cannot directly verify the logger call without a seam.

I will create a minimal test that calls the method with a null clusterProvider or other null dependency to cause an exception and verify the error result.

